import{_ as t,c as s,o as r,ag as e}from"./chunks/framework.Cycwnjj0.js";const a="/assets/custom-prducts-from-azonpress-dashboard.DtU-T_mS.webp",d="/assets/add-products-popup-page.DKuzLDvM.webp",n="/assets/custom-product-dashboard.ClKMezvF.webp",y=JSON.parse('{"title":"Custom Products And Its Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"guide/custom-product/custom-products-and-its-dashboard.md","filePath":"guide/custom-product/custom-products-and-its-dashboard.md"}'),u={name:"guide/custom-product/custom-products-and-its-dashboard.md"};function i(c,o,p,h,l,g){return r(),s("div",null,[...o[0]||(o[0]=[e('<h1 id="custom-products-and-its-dashboard" tabindex="-1">Custom Products And Its Dashboard <a class="header-anchor" href="#custom-products-and-its-dashboard" aria-label="Permalink to &quot;Custom Products And Its Dashboard&quot;">​</a></h1><p>AzonPress allows you to add <strong>Custom Product/s</strong> for your website where you can add <strong>single</strong> or <strong>multiple</strong> custom products with affiliate links. With this feature, besides Amazon, you can also fetch data from other E-Commerce websites such as eBay and Etsy. This article guides you through adding Custom Product/s with AzonPress and gives an overview of the <strong>Custom Product Dashboard.</strong></p><h2 id="add-custom-product-s" tabindex="-1">Add Custom Product/s <a class="header-anchor" href="#add-custom-product-s" aria-label="Permalink to &quot;Add Custom Product/s&quot;">​</a></h2><p>To learn how to add Custom Product/s with AzonPress, follow the steps with the screenshots below –</p><p>First, go to <strong>Custom Products</strong> from the <strong>WordPress Sidebar</strong> or <strong>AzonPress Navbar</strong>. Now, click the <strong>Add Custom Product</strong> button and a popup page will appear.</p><p><img src="'+a+'" alt="Custom Products from AzonPress Dashboard"></p><p>Now, select the <strong>Single Product Template</strong> option if you want to add a single custom product. Or, select the <strong>Multiple Product Template</strong> option for adding multiple custom products.</p><p>Then, enter the <strong>Link</strong> of the <strong>Amazon product</strong> that you want to add as a custom product under the <strong>URL</strong> field and press <strong>Continue</strong>. Your custom product/s will be added!</p><p><strong><em>For example, here I have added a single Amazon product as a custom product.</em></strong></p><p><img src="'+d+'" alt="Add products popup page"></p><h2 id="dashboard-overview-of-custom-products" tabindex="-1">Dashboard Overview Of Custom Products <a class="header-anchor" href="#dashboard-overview-of-custom-products" aria-label="Permalink to &quot;Dashboard Overview Of Custom Products&quot;">​</a></h2><p>The details of the whole Dashboard to manage your custom products are given below with a screenshot.</p><ol><li>With this <strong>Search</strong> option, you can easily find the custom product you are looking for by typing the <strong>Title</strong> or <strong>ID</strong> of your desired product.</li><li>By pressing this <strong>Button</strong> you can <strong>add new custom product/s</strong> to your website as many as you want.</li><li>This section shows the unique <strong>ID</strong> number for each of the custom products you have added to your website.</li><li>The <strong>Title</strong> will show you the names of the custom products you have added to your websites.</li><li>The <strong>Shortcode</strong> option provides the specific shortcodes for each custom product so that you can add your custom products to your desired <strong>page</strong> or <strong>post</strong> on your website.</li><li><strong>Clocked URL</strong> gives you the <strong>Product Link</strong> of your custom products so that you can add these products anytime on your other pages, blogs, posts, or anywhere by simply copying those.</li><li>This option shows how many <strong>Product links</strong> are available on the <strong>Multiple Custom Product</strong> page.</li><li>This button will show you a <strong>Preview</strong> of the details of your custom products.</li><li>Using this button, you can <strong>Edit</strong> your added custom products.</li><li>With this option, you can <strong>Delete</strong> any of our existing custom products at any time.</li><li>This is the <strong>Pagination</strong> option where you can <strong>set the limit</strong> of how many custom products will be shown per page.</li></ol><p><img src="'+n+'" alt="Custom Product Dashboard"></p><p>This is all about your custom product dashboard!</p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',17)])])}const b=t(u,[["render",i]]);export{y as __pageData,b as default};
